files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --green: #00b894;
  --red: #e17055;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  padding: 32px 24px;
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  text-align: center;
  width: 100%;
  max-width: 420px;
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 8px;
}

.subtitle {
  font-size: 1rem;
  opacity: 0.8;
  margin-bottom: 24px;
}

.box {
  width: 100%;
  aspect-ratio: 1 / 1;
  max-height: 260px;
  background: #3a3a55;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s, transform 0.1s;
  margin-bottom: 24px;
  outline: none;
}

.box:hover {
  filter: brightness(1.1);
}

.box:focus-visible {
  box-shadow: 0 0 0 4px var(--accent);
}

.box:active {
  transform: scale(0.97);
}

.box.waiting {
  background: var(--red);
}

.box.ready {
  background: var(--green);
}

.box.early {
  background: var(--red);
}

.controls {
  margin-bottom: 16px;
}

.btn {
  font-family: var(--font);
  font-size: 1.1rem;
  padding: 12px 32px;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  font-weight: 600;
  transition: background 0.2s, transform 0.1s;
}

.btn.primary {
  background: var(--accent);
  color: var(--text);
}

.btn.primary:hover {
  background: #7d6ff0;
}

.btn.primary:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn.primary:active {
  transform: scale(0.96);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.stats {
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  gap: 12px;
}

.result {
  min-height: 1.4em;
  font-weight: 600;
}

.best {
  opacity: 0.8;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .box {
    font-size: 1.2rem;
  }
}

const box = document.getElementById('box');
const boxText = document.getElementById('boxText');
const startBtn = document.getElementById('startBtn');
const resultEl = document.getElementById('result');
const bestEl = document.getElementById('best');

let state = 'idle'; // idle | waiting | ready | early | done
let timeoutId = null;
let startTime = 0;
let bestTime = null;

startBtn.addEventListener('click', startTest);
box.addEventListener('click', handleBoxClick);
box.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    handleBoxClick();
  }
});

function startTest() {
  if (state === 'waiting' || state === 'ready') return;
  clearTimeout(timeoutId);
  state = 'waiting';
  box.className = 'box waiting';
  boxText.textContent = 'Wait for green...';
  resultEl.textContent = '—';
  startBtn.disabled = true;
  const delay = 1000 + Math.random() * 4000;
  timeoutId = setTimeout(() => {
    state = 'ready';
    box.className = 'box ready';
    boxText.textContent = 'Click!';
    startTime = performance.now();
  }, delay);
}

function handleBoxClick() {
  if (state === 'waiting') {
    clearTimeout(timeoutId);
    state = 'early';
    box.className = 'box early';
    boxText.textContent = 'Too soon!';
    resultEl.textContent = 'Too soon!';
    startBtn.disabled = false;
    return;
  }
  if (state === 'ready') {
    const reaction = Math.round(performance.now() - startTime);
    state = 'done';
    box.className = 'box';
    boxText.textContent = 'Press Start';
    resultEl.textContent = reaction + ' ms';
    if (bestTime === null || reaction < bestTime) {
      bestTime = reaction;
      bestEl.textContent = 'Best: ' + bestTime + ' ms';
    }
    startBtn.disabled = false;
  }
}
